NEG = r'англ|English|немецк|французск|физическ\w+ (подготовк|культур)|огнев\w+ подготовк|стрельб|рукопашн|борьб|гимнастик|плавани|лыжн|атлет|математик|философ|русск\w+ язык|культур\w+ речи|риторик|экономическ\w+ теори|бухгалтер|финансов\w+ право|налогов|земельн|жилищн|семейн|наследств|уголовно-исполнительн|исполнени\w+ наказани|осужденн|несовершеннолетн|ювенальн|миграц|иностранн\w+ (граждан|слушател|обучающ)|наркот|экстремиз|террори|массов\w+ (беспорядк|мероприят)|публичн\w+ мероприят|кинолог|служебн\w+ собак|мошеннич|хищен|киберпреступ|информационно-телекоммуникационн|незаконн\w+ (оборот|предприним|рубк)|убийств|изнасилован|краж|грабеж|грабёж|разбо|побо|алимент|участков|УУП|экологич|лесо|самоубийств|суицид|беспилотн|блокированн|спирт|алкогольн|легализац|предпринимательск|вымогательств|выдач|топограф|гражданск\w+ (процесс|прав)|трудов\w+ прав|охран\w+ труда|административн\w+ надзор\w* за лицами|под административным надзором|санитарн|эпидеми|оружи\w+ массового|иерархи|IT-|банковск|электронн\w+ средств платежа|организованн|клиническ|методика преподавания|LibreOffice|баз\w* данных|геоинформ|интервенц|консультирован|малой групп|PR-|насильствен|нарушениями слуха|многоязычн|массовой информации в услов|6\.13|20\.3|7\.27|6\.1\.1|железнодорожн|продовольств|закупок|почерк|экспертиза документов|призывом|европейского суда|вневедомственн|конвой|сыска|экономическ|компьютерн\w+ информац|криптограф'
# исключения: слова, при которых издание не берётся, хотя общий признак сработал
DROP_G = r'железнодорожн|возмещени\w+ вреда|публичных коммуникаций'
DROP_G1 = r'огнестрельное оружие и его следы|информационных технологий для совершенствования'
DROP_S = r'тяжкого вреда|умершего|международн\w+ сотрудничеств|биологическ|региональн|приостановлен|электронных носител|заключение под стражу|субъектов финанс|прекращении уголовного преследования|дистанционн|судебных экспертиз на стадии|адаптации сотрудников подразделений дознания'
DROP_S2 = r'научной деятельности|почерк|экспертиза документов|суицид\w* несовершеннолетн|продовольств|неправомерного доступа|компьютерной информации|криптограф|физические основы'
UCH = ('учебник', 'курс лекций', 'учебно-методическое пособие', 'учебно-практическое пособие', 'учебное наглядное пособие', 'учебное пособие',
       'практикум', 'практическое пособие', 'методические рекомендации', 'справочное пособие', 'комментарий')
KINDS = [('учебник', r'\bучебник'), ('курс лекций', r'курс лекций|лекци[яи]\b'), ('учебно-методическое пособие', r'учебно-\s?методическ\w+ пособи|учеб\.-метод'),
         ('учебно-практическое пособие', r'учебно-\s?практическ\w+ пособи|учеб\.-практ'), ('учебное наглядное пособие', r'нагляд\w+ пособи|альбом схем|в схемах|схемы и'),
         ('учебное пособие', r'учебн\w+ пособи|учеб\. пособие'), ('практикум', r'практикум|задачник|сборник задач|задачи и тест|макет'),
         ('практическое пособие', r'практическ\w+ пособи|научно-практическ\w+ пособи|памятк|алгоритм'), ('методические рекомендации', r'методическ\w+ (рекомендац|указан|пособи|материал)'),
         ('справочное пособие', r'справочн|словарь|глоссарий'), ('комментарий', r'комментари'),
         ('монография', r'монографи'), ('сборник', r'сборник|материалы|конференц|круглого стола|чтени[яй]'), ('журнал', r'журнал|вестник|Editor|бюллетень|труды'),
         ('обзор', r'обзор|аналитическ'), ('отчёт', r'отч[её]т|научно-исследовательск\w+ работ')]
ORG = r'(МИНИСТЕРСТВ\w+ ВНУТРЕННИХ ДЕЛ РОССИЙСКОЙ ФЕДЕРАЦИИ|Министерств\w+ внутренних дел Российской Федерации|МВД России|МВД РОССИИ|ФЕДЕРАЛЬНОЕ ГОСУДАРСТВЕННОЕ [А-ЯЁ ]+УЧРЕЖДЕНИЕ( ВЫСШЕГО ОБРАЗОВАНИЯ)?|Федеральное государственное [а-яё ]+учреждение( высшего образования)?|[А-ЯЁа-яё\-]+ (ЮРИДИЧЕСКИЙ )?(УНИВЕРСИТЕТ|ИНСТИТУТ|АКАДЕМИЯ)|[А-ЯЁа-яё\-]+ (юридический )?(университет|институт|академия)( управления)?|имени [А-ЯЁ]\.\s?[А-ЯЁ]\.\s?[А-ЯЁ][а-яё]+|ИМЕНИ [А-ЯЁ. ]+|[А-ЯЁа-яё]+ филиал|Кафедра [а-яё ,]+|ГЛАВНОЕ УПРАВЛЕНИЕ [А-ЯЁ ]+ДВИЖЕНИЯ|НАУЧНЫЙ ЦЕНТР БЕЗОПАСНОСТИ ДОРОЖНОГО ДВИЖЕНИЯ|ВСЕРОССИЙСКИЙ НАУЧНО-ИССЛЕДОВАТЕЛЬСКИЙ ИНСТИТУТ|\(?ФГК[ОУ]+ [^)]{0,60}\)|«|»|_{3,}|УДК [\d.:]+|ББК [\d.я]+|Российской Федерации|РОССИЙСКОЙ ФЕДЕРАЦИИ|Министерств\w+ (внутренних дел|науки и высшего образования)|МИНИСТЕРСТВ\w+ (ВНУТРЕННИХ ДЕЛ|НАУКИ И ВЫСШЕГО ОБРАЗОВАНИЯ)|Ордена Трудового Красного Знамени|Главное управление по работе с личным составом)'

def hits(rx, t): return len(set(m.group(0).lower()[:10] for m in re.finditer(rx, t, re.I)))
def dehyph(s): return re.sub(r'(?<=[а-яё])-\s+(?=[а-яё])', '', s or '')
def cls(title, toc=''):
    """-> (g, s): 2 — профильное издание, 1 — смежное, 0 — не относится."""
    t = ' '.join(title.split()); ng = hits(NEG, t)
    g = 2 if hits(G_STRONG, t) else (1 if hits(G_WIDE, t) and not ng else 0)
    s = 2 if hits(S_STRONG, t) else (1 if hits(S_REL, t) and not ng else 0)
    if toc and not ng:   # оглавление: только сильные признаки и только при четырёх разных совпадениях
        if g < 2 and hits(G_STRONG, toc) >= 4: g = 2
        if s < 2 and hits(S_STRONG, toc) >= 4: s = 2
    if g == 2 and re.search(DROP_G, t, re.I): g = 0
    if g == 1 and (s == 2 and not re.search(r'административн', t, re.I) or re.search(DROP_G1, t, re.I)): g = 0
    if s == 1 and re.search(DROP_S, t, re.I): s = 0
    if s == 2 and re.search(DROP_S2, t, re.I): s = 0
    return g, s
def norm(t): return re.sub(r'[^а-яёa-z0-9]', '', dehyph(t).lower().replace('[электронный ресурс]', ''))[:70]
def year_of(v):
    m = re.search(r'20\d\d', str(v or '')); return int(m.group(0)) if m else 0
def lib_year(p):
    ys = [int(y) for y in re.findall(r'/(20[12]\d)(?=[ /_.\-])', '/' + p)]; return max(ys) if ys else 0

# ---------- уже имеющиеся издания ----------
def existing():
    out = []
    for f in sorted(glob.glob(DL + '/**/manifest*.json', recursive=True)):
        code = re.sub(r'.*manifest_?|\.json', '', f)
        for e in json.load(open(f, encoding='utf-8')):
            dst = e.get('dst', '')
            if '3. Учебная литература' not in dst: continue
            if not dst.startswith(tuple(OLD.values()) + ('Административная', 'Криминалистика')):
                dst = OLD.get(code, '?') + '/2. Источники/' + dst
            if not os.path.exists(os.path.join(ROOT, dst)): continue
            y = year_of(e.get('year'))
            if y < 2023: continue
            out.append(dict(n='e' + hashlib.md5(dst.encode()).hexdigest()[:6], src=dst, url=e.get('url', ''), title=dehyph(e.get('title', '')), kind=(e.get('kind') or '').lower(),
                            authors=e.get('authors', ''), pub=e.get('pub', ''), year=y, pages=int(e.get('pages') or 0), size=os.path.getsize(os.path.join(ROOT, dst)),
                            name=os.path.basename(dst), origin='база дисциплины «%s»' % dst.split('/')[0]))
    return out

# ---------- новые издания (просмотр первых страниц) ----------
def kind_of(d, head, cat):
    if d and d['kind'] != 'издание':
        k = dehyph(d['kind'])
        for name, rx in KINDS:
            if re.search(rx, k, re.I): return name
        return k
    if cat == 'Периодика': return 'журнал'
    best = None
    for name, rx in KINDS:
        m = re.search(rx, head[:900], re.I)
        if m and (best is None or m.start() < best[0]): best = (m.start(), name)
    return best[1] if best else '?'
def title_of(d, head):
    if d: return dehyph(d['title'])
    h = re.sub(ORG, ' ¦ ', head[:600]); parts = [p.strip(' .,–-') for p in h.split('¦')]
    parts = [p for p in parts if len(re.findall('[А-Яа-яЁё]', p)) >= 12]
    return (parts[0] if parts else head[:120])[:230]
def peeked():
    out = []
    for f in sorted(glob.glob(HERE + '/peek[0-9]*.tsv')):
        for l in open(f, encoding='utf-8'):
            r = l.rstrip('\n').split('\t') + [''] * 6
            url = U.unquote(r[0]); p = url[len(P):]; a = p.split('/')
            head, toc = r[4], r[5]
            d = bib.describe(head) if head else None
            ys = [int(y) for y in re.findall(r'\b(20[012]\d)\b', head[:1100])]
            out.append(dict(n='b' + hashlib.md5(url.encode()).hexdigest()[:6], url=url, size=int(r[1] or 0), pages=int(r[2] or 0), flag=r[3], toc=toc, head=head,
                            lyear=lib_year(p), hyear=int(d['year']) if d else (max(ys) if ys else 0), cat=a[2] if len(a) > 3 else a[1],
                            short=re.sub(r'^20\d\d\s*', '', a[3]) if len(a) > 4 else os.path.splitext(a[-1])[0],
                            title=title_of(d, head), kind=kind_of(d, head, a[2] if len(a) > 3 else ''), bib=bool(d)))
    return out

def select():
    ex = existing(); new = peeked()
    sel = []; seen = {}; skipped = []; nxt = []
    st = collections.Counter()
    def take(e, g, s, why=''):
        key = (e['pages'], e['size'])
        key2 = (norm(e['title']), e['pages'])
        for k in (key, key2):
            if k in seen and k[0]:
                o = seen[k]; o['g'] = max(o['g'], g); o['s'] = max(o['s'], s); st['повтор'] += 1; return
        e['g'], e['s'] = g, s; sel.append(e); seen[key] = e; seen[key2] = e
    for e in ex:
        g, s = cls(e['title'])
        if g or s: take(e, g, s)
        else: st['имеющиеся: не относятся'] += 1
    for e in new:
        if e['hyear'] and e['hyear'] < 2023 or not e['hyear'] and e['lyear'] < 2023:
            st['новые: издание старше 2023 года'] += 1; skipped.append((e, 'издание старше 2023 года (%s)' % (e['hyear'] or 'год не определён'))); continue
        g, s = cls(e['title'] + ' | ' + e['short'], e['toc'])
        if not g and not s: st['новые: не относятся'] += 1; continue
        if 'ДСП' in e['flag']: st['новые: пометка об ограничении доступа'] += 1; skipped.append((e, 'в тексте пометка об ограничении доступа — не берётся')); continue
        if 'нет текстового слоя' in e['flag']: st['новые: нет текстового слоя'] += 1; skipped.append((e, 'нет текстового слоя — название и год не проверить')); continue
        if e['kind'] not in UCH:
            st['новые: не учебное издание (%s)' % e['kind']] += 1; nxt.append((e, g, s)); continue
        if e['size'] > MAXSIZE: skipped.append((e, 'файл крупнее 99 МБ')); continue
        take(e, g, s)
    for e in sel:
        st['отобрано: ' + ('есть в базе' if e['n'][0] == 'e' else 'новое')] += 1
        if e['g']: st['G'] += 1; st['G объём, МБ'] += e['size'] / 1e6
        if e['s']: st['S'] += 1; st['S объём, МБ'] += e['size'] / 1e6
        if e['n'][0] == 'b': st['к загрузке, МБ'] += e['size'] / 1e6
    json.dump([{k: v for k, v in e.items() if k not in ('head', 'toc')} for e in sel], open(HERE + '/sel.json', 'w', encoding='utf-8'), ensure_ascii=False, indent=0)
    with open(HERE + '/next_stages.tsv', 'w', encoding='utf-8') as f:
        f.write('# научные и аналитические издания библиотеки 2023 года и новее, относящиеся к дисциплинам: на этапы 4 и 5\n# G\tS\tвид\tстраниц\tбайт\tназвание\tадрес\n')
        for e, g, s in sorted(nxt, key=lambda x: (x[0]['kind'], x[0]['title'])):
            f.write('\t'.join(map(str, (g, s, e['kind'], e['pages'], e['size'], e['title'][:200], e['url']))) + '\n')
    with open(HERE + '/skipped.tsv', 'w', encoding='utf-8') as f:
        f.write('# издания, просмотренные и не взятые\n# причина\tназвание\tадрес\n')
        for e, why in skipped:
            g, s = cls(e['title'] + ' | ' + e['short'], e['toc'])
            if g or s: f.write('\t'.join((why, e['title'][:200], e['url'])) + '\n')
    for k, v in sorted(st.items()): print('  %s: %s' % (k, round(v) if isinstance(v, float) else v))
    return sel

def shards(prefix, n=10):
    sel = [e for e in json.load(open(HERE + '/sel.json', encoding='utf-8')) if e['n'][0] == 'b']
    sel.sort(key=lambda e: -e['size']); b = [[] for _ in range(n)]; tot = [0] * n
    for e in sel:
        i = tot.index(min(tot)); b[i].append(e); tot[i] += e['size'] + 500000
    for i, x in enumerate(b, 1):
        with open(DL + '/shards/%s_lit%02d.tsv' % (prefix, i), 'w', encoding='utf-8') as f:
            for e in x: f.write('get\t%s\t.work/lit3/%s.pdf\n' % (U.quote(e['url'], safe=':/%'), e['n']))
    print([len(x) for x in b], [int(t / 1e6) for t in tot])

if __name__ == '__main__':
    cmd = sys.argv[1] if len(sys.argv) > 1 else ''
    if cmd == 'select': select()
    elif cmd == 'shards': shards(sys.argv[2])
    elif cmd == 'place': import lit_place; lit_place.run()
    elif cmd == 'registry': import lit_place; lit_place.registry()
    else: print(__doc__)
